// reuse-precreated: one function created once at module scope, no closure creation in the loop -- the baseline
// lifetime retain: odd run() calls fill N already-null
// preallocated slots (N creations, no release); even run() calls
// clear them (N releases, no creation). The harness times one run()
// call per sample, so with an even --warmup the odd-indexed samples
// are creation-only and the even-indexed samples are release-only.
const N = 20000;
const F = (x) => x + 1;
const slots = new Array(N);
for (let i = 0; i < N; i++) slots[i] = null;
let calls = 0;
let acc = 0;
function run() {
    calls += 1;
    acc = 0;
    if ((calls & 1) === 1) {
        for (let i = 0; i < N; i++) {
            slots[i] = F;
        }
        return calls * 1000000 + acc * 1000 + slots[N - 1](1);
    }
    for (let i = 0; i < N; i++) slots[i] = null;
    return calls * 1000000;
}
print(run());
